-- Customer CRM (crm/index.html) — tables, sequence, indexes, the customer pages (WMS_CRM_PORTAL / WMS_CRM_TK) and their ORDS endpoints.
-- The page creates all of this itself (Setup › Database); this file is the same DDL for a DBA. Generated from crm/crm-store.js.
-- Statements, Debtors cards and the Debtors timeline are the Debtors Control tables (apex_sql/99_debtors_control.sql).

CREATE TABLE wms_crm_settings (skey VARCHAR2(60) PRIMARY KEY, sval CLOB, changed_by VARCHAR2(100), changed_date DATE DEFAULT SYSDATE);

CREATE TABLE wms_crm_tickets (ticket_id VARCHAR2(40) PRIMARY KEY, ticket_no VARCHAR2(30), pod VARCHAR2(20), bu_id VARCHAR2(30), account_number VARCHAR2(60), account_name VARCHAR2(360), contact_name VARCHAR2(200), contact_email VARCHAR2(320), contact_phone VARCHAR2(60), subject VARCHAR2(400), description VARCHAR2(4000), category VARCHAR2(100), subcategory VARCHAR2(100), priority VARCHAR2(4) DEFAULT 'P3', status VARCHAR2(20) DEFAULT 'NEW', channel VARCHAR2(20), queue VARCHAR2(100), assigned_to VARCHAR2(100), order_number VARCHAR2(60), invoice_number VARCHAR2(60), item_number VARCHAR2(100), tags VARCHAR2(400), due_first DATE, due_resolve DATE, first_response_at DATE, resolved_at DATE, closed_at DATE, paused_at DATE, resolution VARCHAR2(4000), reopened_n NUMBER DEFAULT 0, csat NUMBER, csat_comment VARCHAR2(1000), csat_at DATE, ai_category VARCHAR2(100), ai_conf NUMBER, token VARCHAR2(64), last_customer_at DATE, parent_id VARCHAR2(40), created_by VARCHAR2(100), created_at DATE DEFAULT SYSDATE, changed_by VARCHAR2(100), changed_date DATE DEFAULT SYSDATE);

CREATE TABLE wms_crm_ticket_events (event_id VARCHAR2(40) PRIMARY KEY, ticket_id VARCHAR2(40) NOT NULL, kind VARCHAR2(20), body VARCHAR2(4000), visibility VARCHAR2(10) DEFAULT 'INTERNAL', meta VARCHAR2(2000), by_user VARCHAR2(100), event_at DATE DEFAULT SYSDATE);

CREATE TABLE wms_crm_calls (call_id VARCHAR2(40) PRIMARY KEY, direction VARCHAR2(3), number_raw VARCHAR2(60), number_e164 VARCHAR2(30), bu_id VARCHAR2(30), account_number VARCHAR2(60), account_name VARCHAR2(360), contact_name VARCHAR2(200), agent VARCHAR2(100), machine VARCHAR2(100), started_at DATE, answered_at DATE, ended_at DATE, duration_s NUMBER, outcome VARCHAR2(20), disposition VARCHAR2(100), notes VARCHAR2(4000), ticket_id VARCHAR2(40), recording_path VARCHAR2(600), recording_sha VARCHAR2(64), recording_bytes NUMBER, source VARCHAR2(20) DEFAULT 'MANUAL', external_id VARCHAR2(100), callback_at DATE, callback_done VARCHAR2(1) DEFAULT 'N', created_at DATE DEFAULT SYSDATE);

CREATE TABLE wms_crm_messages (msg_id VARCHAR2(40) PRIMARY KEY, direction VARCHAR2(3) DEFAULT 'OUT', channel VARCHAR2(20) DEFAULT 'EMAIL', bu_id VARCHAR2(30), account_number VARCHAR2(60), account_name VARCHAR2(360), to_addr VARCHAR2(1000), cc_addr VARCHAR2(1000), subject VARCHAR2(400), body VARCHAR2(4000), attachments VARCHAR2(2000), ticket_id VARCHAR2(40), stmt_id VARCHAR2(40), status VARCHAR2(20), error_text VARCHAR2(2000), method VARCHAR2(20), mailbox VARCHAR2(320), by_user VARCHAR2(100), machine VARCHAR2(100), created_at DATE DEFAULT SYSDATE, sent_at DATE);

CREATE TABLE wms_crm_contacts (contact_id VARCHAR2(40) PRIMARY KEY, bu_id VARCHAR2(30), account_number VARCHAR2(60), name VARCHAR2(200), role VARCHAR2(100), email VARCHAR2(320), phone VARCHAR2(60), mobile VARCHAR2(60), is_primary VARCHAR2(1) DEFAULT 'N', notes VARCHAR2(1000), removed VARCHAR2(1) DEFAULT 'N', created_by VARCHAR2(100), created_at DATE DEFAULT SYSDATE, changed_by VARCHAR2(100), changed_date DATE DEFAULT SYSDATE);

CREATE SEQUENCE wms_crm_ticket_seq START WITH 1 INCREMENT BY 1 NOCACHE;

CREATE INDEX wms_crm_tk_acct ON wms_crm_tickets (account_number);
CREATE INDEX wms_crm_tk_status ON wms_crm_tickets (status);
CREATE INDEX wms_crm_tk_tok ON wms_crm_tickets (token);
CREATE INDEX wms_crm_ev_tk ON wms_crm_ticket_events (ticket_id);
CREATE INDEX wms_crm_call_acct ON wms_crm_calls (account_number);
CREATE INDEX wms_crm_call_e164 ON wms_crm_calls (number_e164);
CREATE INDEX wms_crm_msg_acct ON wms_crm_messages (account_number);
CREATE INDEX wms_crm_ct_acct ON wms_crm_contacts (account_number);

-- WMS_CRM_PORTAL — the customer page that raises a ticket
CREATE OR REPLACE PROCEDURE wms_crm_portal (p_key IN VARCHAR2, p_post IN VARCHAR2, p_name IN VARCHAR2, p_email IN VARCHAR2, p_phone IN VARCHAR2, p_account IN VARCHAR2, p_company IN VARCHAR2, p_subject IN VARCHAR2, p_text IN VARCHAR2, p_category IN VARCHAR2) AS v_ok NUMBER; v_id VARCHAR2(40); v_no VARCHAR2(30); v_tok VARCHAR2(64); v_prefix VARCHAR2(10) := 'CS-'; v_cats VARCHAR2(4000); v_opts VARCHAR2(4000); v_cat VARCHAR2(100); v_n NUMBER; PROCEDURE page (p_title IN VARCHAR2, p_body IN VARCHAR2) IS BEGIN OWA_UTIL.mime_header('text/html', FALSE, 'UTF-8'); HTP.p('Cache-Control: no-store'); OWA_UTIL.http_header_close; HTP.p('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>' || HTF.escape_sc(p_title) || '</title><style>body{margin:0;font:15px/1.5 "Segoe UI",Arial,sans-serif;background:#eef0fb;color:#0f172a}.c{max-width:640px;margin:6vh auto;background:#fff;border-radius:14px;padding:28px 32px;box-shadow:0 10px 30px rgba(15,23,42,.1)}h1{font-size:21px;margin:0 0 6px}.m{color:#64748b;font-size:13px}label{display:block;font-size:13px;font-weight:600;color:#334155;margin:12px 0 4px}input,textarea,select{width:100%;box-sizing:border-box;border:1px solid #cbd5e1;border-radius:9px;padding:9px 11px;font:inherit}textarea{min-height:120px}button{margin-top:16px;background:#4338ca;color:#fff;border:0;border-radius:9px;padding:11px 18px;font-weight:700;font-size:15px;cursor:pointer}.ok{color:#15803d;font-weight:700}.ev{border-left:3px solid #c7d2fe;padding:6px 12px;margin:10px 0}.ev.cu{border-color:#94a3b8}.ev .w{font-size:12px;color:#64748b}.st{display:inline-block;background:#e0e7ff;color:#3730a3;border-radius:99px;padding:2px 10px;font-size:12px;font-weight:700}.stars{display:flex;gap:6px;flex-wrap:wrap}.stars label{margin:0;font-weight:500}.f{margin-top:22px;font-size:12px;color:#94a3b8}</style></head><body><div class="c">'); HTP.p(p_body); HTP.p('<div class="f">Customer care</div></div></body></html>'); END; BEGIN SELECT COUNT(*) INTO v_ok FROM wms_crm_settings WHERE skey = 'PORTAL_KEY' AND TO_CHAR(SUBSTR(sval, 1, 200)) = '"' || p_key || '"' AND LENGTH(p_key) >= 12; IF v_ok = 0 THEN page('Not available', '<h1>This page is not available</h1><p class="m">The link may be out of date. Please contact us by phone or e-mail.</p>'); RETURN; END IF; BEGIN SELECT REPLACE(TO_CHAR(SUBSTR(sval, 1, 3900)), '"', '') INTO v_cats FROM wms_crm_settings WHERE skey = 'PORTAL_CATEGORIES'; EXCEPTION WHEN NO_DATA_FOUND THEN v_cats := NULL; END; BEGIN SELECT REPLACE(TO_CHAR(SUBSTR(sval, 1, 20)), '"', '') INTO v_prefix FROM wms_crm_settings WHERE skey = 'PREFIX'; EXCEPTION WHEN NO_DATA_FOUND THEN v_prefix := 'CS-'; END; IF p_post = 'Y' THEN IF TRIM(p_subject) IS NULL OR TRIM(p_text) IS NULL OR (TRIM(p_email) IS NULL AND TRIM(p_phone) IS NULL) THEN page('Contact us', '<h1>Something is missing</h1><p class="m">Please go back and fill in the subject, the description and an e-mail or phone number.</p>'); RETURN; END IF; SELECT COUNT(*) INTO v_n FROM wms_crm_tickets WHERE channel = 'PORTAL' AND created_at > SYSDATE - 1/24 AND (LOWER(contact_email) = LOWER(TRIM(p_email)) OR contact_phone = TRIM(p_phone)); IF v_n >= 5 THEN page('Contact us', '<h1>Thank you</h1><p class="m">We already received several requests from you in the last hour; our team will be in touch.</p>'); RETURN; END IF; v_cat := CASE WHEN v_cats IS NOT NULL AND INSTR(v_cats, '|' || p_category || '|') > 0 THEN p_category ELSE NULL END; v_id := 'tk' || LOWER(RAWTOHEX(SYS_GUID())); v_tok := LOWER(RAWTOHEX(SYS_GUID())) || LOWER(RAWTOHEX(SYS_GUID())); INSERT INTO wms_crm_tickets (ticket_id, ticket_no, account_number, account_name, contact_name, contact_email, contact_phone, subject, description, category, priority, status, channel, token, last_customer_at, created_by, created_at, changed_by, changed_date) VALUES (v_id, v_prefix || LPAD(wms_crm_ticket_seq.NEXTVAL, 6, '0'), SUBSTR(TRIM(p_account), 1, 60), SUBSTR(TRIM(p_company), 1, 360), SUBSTR(TRIM(p_name), 1, 200), SUBSTR(TRIM(p_email), 1, 320), SUBSTR(TRIM(p_phone), 1, 60), SUBSTR(TRIM(p_subject), 1, 400), SUBSTR(p_text, 1, 4000), v_cat, 'P3', 'NEW', 'PORTAL', v_tok, SYSDATE, 'customer', SYSDATE, 'customer', SYSDATE) RETURNING ticket_no INTO v_no; INSERT INTO wms_crm_ticket_events (event_id, ticket_id, kind, body, visibility, by_user, event_at) VALUES ('ev' || LOWER(RAWTOHEX(SYS_GUID())), v_id, 'CREATED', 'Raised on the customer page', 'PUBLIC', 'customer', SYSDATE); COMMIT; page('Request received', '<h1>Thank you — we have your request</h1><p>Your reference is <b>' || HTF.escape_sc(v_no) || '</b>.</p><p class="m">Keep this link to follow it and to reply: <a href="../t/' || v_tok || '">see my request</a></p>'); RETURN; END IF; IF v_cats IS NOT NULL THEN v_opts := '<label>What is it about?</label><select name="category"><option value="">Choose…</option>'; FOR c IN (SELECT REGEXP_SUBSTR(v_cats, '[^|]+', 1, LEVEL) AS n FROM dual CONNECT BY REGEXP_SUBSTR(v_cats, '[^|]+', 1, LEVEL) IS NOT NULL) LOOP v_opts := v_opts || '<option>' || HTF.escape_sc(c.n) || '</option>'; END LOOP; v_opts := v_opts || '</select>'; END IF; page('Contact us', '<h1>How can we help?</h1><p class="m">Tell us what happened and we will get back to you. You will get a reference number.</p><form method="post">' || '<label>Your name</label><input name="name" maxlength="200" required><label>E-mail</label><input name="email" type="email" maxlength="320"><label>Phone</label><input name="phone" maxlength="60">' || '<label>Company</label><input name="company" maxlength="360"><label>Customer account number (if you know it)</label><input name="account" maxlength="60">' || v_opts || '<label>Subject</label><input name="subject" maxlength="400" required><label>Description</label><textarea name="text" maxlength="4000" required placeholder="Order or invoice numbers help us a lot"></textarea><button type="submit">Send my request</button></form>'); END wms_crm_portal;
/

-- WMS_CRM_TK — the customer's view of a ticket: reply, rate
CREATE OR REPLACE PROCEDURE wms_crm_tk (p_tok IN VARCHAR2, p_post IN VARCHAR2, p_text IN VARCHAR2, p_rate IN VARCHAR2, p_comment IN VARCHAR2) AS v_id VARCHAR2(40); v_no VARCHAR2(30); v_subj VARCHAR2(400); v_status VARCHAR2(20); v_csat NUMBER; v_body VARCHAR2(32000); v_label VARCHAR2(60); PROCEDURE page (p_title IN VARCHAR2, p_body IN VARCHAR2) IS BEGIN OWA_UTIL.mime_header('text/html', FALSE, 'UTF-8'); HTP.p('Cache-Control: no-store'); OWA_UTIL.http_header_close; HTP.p('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>' || HTF.escape_sc(p_title) || '</title><style>body{margin:0;font:15px/1.5 "Segoe UI",Arial,sans-serif;background:#eef0fb;color:#0f172a}.c{max-width:640px;margin:6vh auto;background:#fff;border-radius:14px;padding:28px 32px;box-shadow:0 10px 30px rgba(15,23,42,.1)}h1{font-size:21px;margin:0 0 6px}.m{color:#64748b;font-size:13px}label{display:block;font-size:13px;font-weight:600;color:#334155;margin:12px 0 4px}input,textarea,select{width:100%;box-sizing:border-box;border:1px solid #cbd5e1;border-radius:9px;padding:9px 11px;font:inherit}textarea{min-height:120px}button{margin-top:16px;background:#4338ca;color:#fff;border:0;border-radius:9px;padding:11px 18px;font-weight:700;font-size:15px;cursor:pointer}.ok{color:#15803d;font-weight:700}.ev{border-left:3px solid #c7d2fe;padding:6px 12px;margin:10px 0}.ev.cu{border-color:#94a3b8}.ev .w{font-size:12px;color:#64748b}.st{display:inline-block;background:#e0e7ff;color:#3730a3;border-radius:99px;padding:2px 10px;font-size:12px;font-weight:700}.stars{display:flex;gap:6px;flex-wrap:wrap}.stars label{margin:0;font-weight:500}.f{margin-top:22px;font-size:12px;color:#94a3b8}</style></head><body><div class="c">'); HTP.p(p_body); HTP.p('<div class="f">Customer care</div></div></body></html>'); END; BEGIN BEGIN SELECT ticket_id, ticket_no, subject, status, csat INTO v_id, v_no, v_subj, v_status, v_csat FROM wms_crm_tickets WHERE token = p_tok AND LENGTH(p_tok) >= 24; EXCEPTION WHEN NO_DATA_FOUND THEN page('Not found', '<h1>This link is not valid</h1><p class="m">It may have been copied incompletely.</p>'); RETURN; END; IF p_post = 'Y' THEN IF p_rate IS NOT NULL AND REGEXP_LIKE(p_rate, '^[1-5]$') AND v_csat IS NULL THEN UPDATE wms_crm_tickets SET csat = TO_NUMBER(p_rate), csat_comment = SUBSTR(p_comment, 1, 1000), csat_at = SYSDATE WHERE ticket_id = v_id; INSERT INTO wms_crm_ticket_events (event_id, ticket_id, kind, body, visibility, by_user, event_at) VALUES ('ev' || LOWER(RAWTOHEX(SYS_GUID())), v_id, 'CSAT', 'Rated ' || p_rate || ' / 5' || NVL2(TRIM(p_comment), ': ' || SUBSTR(p_comment, 1, 1000), ''), 'PUBLIC', 'customer', SYSDATE); v_csat := TO_NUMBER(p_rate); END IF; IF TRIM(p_text) IS NOT NULL THEN INSERT INTO wms_crm_ticket_events (event_id, ticket_id, kind, body, visibility, by_user, event_at) VALUES ('ev' || LOWER(RAWTOHEX(SYS_GUID())), v_id, 'CUSTOMER', SUBSTR(p_text, 1, 4000), 'PUBLIC', 'customer', SYSDATE); UPDATE wms_crm_tickets SET last_customer_at = SYSDATE, status = CASE WHEN status IN ('RESOLVED', 'CLOSED', 'PENDING_CUSTOMER') THEN 'OPEN' ELSE status END, reopened_n = NVL(reopened_n, 0) + CASE WHEN status IN ('RESOLVED', 'CLOSED') THEN 1 ELSE 0 END, resolved_at = CASE WHEN status IN ('RESOLVED', 'CLOSED') THEN NULL ELSE resolved_at END, changed_by = 'customer', changed_date = SYSDATE WHERE ticket_id = v_id; END IF; COMMIT; SELECT status INTO v_status FROM wms_crm_tickets WHERE ticket_id = v_id; END IF; v_label := CASE v_status WHEN 'NEW' THEN 'Received' WHEN 'OPEN' THEN 'We are working on it' WHEN 'PENDING_CUSTOMER' THEN 'Waiting for your answer' WHEN 'PENDING_INTERNAL' THEN 'We are working on it' WHEN 'RESOLVED' THEN 'Resolved' WHEN 'CLOSED' THEN 'Closed' ELSE v_status END; v_body := '<div class="m">' || HTF.escape_sc(v_no) || '</div><h1>' || HTF.escape_sc(v_subj) || '</h1><span class="st">' || HTF.escape_sc(v_label) || '</span>'; FOR e IN (SELECT kind, body, by_user, TO_CHAR(event_at, 'DD Mon YYYY HH24:MI') AS w FROM wms_crm_ticket_events WHERE ticket_id = v_id AND visibility = 'PUBLIC' AND kind IN ('CREATED', 'COMMENT', 'CUSTOMER', 'EMAIL_OUT', 'RESOLVED') ORDER BY event_at, event_id) LOOP IF LENGTH(v_body) < 28000 THEN v_body := v_body || '<div class="ev' || CASE WHEN e.kind = 'CUSTOMER' THEN ' cu' END || '"><div class="w">' || CASE WHEN e.kind = 'CUSTOMER' THEN 'You' WHEN e.by_user = 'customer' THEN 'You' ELSE 'Customer care' END || ' · ' || e.w || '</div>' || REPLACE(HTF.escape_sc(SUBSTR(e.body, 1, 2000)), CHR(10), '<br>') || '</div>'; END IF; END LOOP; v_body := v_body || '<form method="post"><label>' || CASE WHEN v_status IN ('RESOLVED', 'CLOSED') THEN 'Not solved? Write to us and the request opens again' ELSE 'Add a message' END || '</label><textarea name="text" maxlength="4000"></textarea>'; IF v_status IN ('RESOLVED', 'CLOSED') AND v_csat IS NULL THEN v_body := v_body || '<label>How did we do?</label><div class="stars">' || '<label><input type="radio" name="rate" value="5" style="width:auto"> 5 Excellent</label><label><input type="radio" name="rate" value="4" style="width:auto"> 4 Good</label><label><input type="radio" name="rate" value="3" style="width:auto"> 3 OK</label><label><input type="radio" name="rate" value="2" style="width:auto"> 2 Poor</label><label><input type="radio" name="rate" value="1" style="width:auto"> 1 Bad</label></div><label>Comment (optional)</label><input name="comment" maxlength="1000">'; ELSIF v_csat IS NOT NULL THEN v_body := v_body || '<p class="ok">Thank you for your rating (' || v_csat || ' / 5).</p>'; END IF; v_body := v_body || '<button type="submit">Send</button></form>'; page(v_no, v_body); END wms_crm_tk;
/

-- crm/new/:key + crm/t/:tok — REST endpoints in the WAREHOUSEMANAGEMENT module
DECLARE v_module VARCHAR2(200); BEGIN SELECT name INTO v_module FROM user_ords_modules WHERE UPPER(uri_prefix) LIKE '%WAREHOUSEMANAGEMENT%' AND ROWNUM = 1; ORDS.DEFINE_TEMPLATE(p_module_name => v_module, p_pattern => 'crm/new/:key'); ORDS.DEFINE_HANDLER(p_module_name => v_module, p_pattern => 'crm/new/:key', p_method => 'GET', p_source_type => ORDS.source_type_plsql, p_source => 'BEGIN wms_crm_portal(:key, ''N'', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL); END;'); ORDS.DEFINE_HANDLER(p_module_name => v_module, p_pattern => 'crm/new/:key', p_method => 'POST', p_source_type => ORDS.source_type_plsql, p_source => 'BEGIN wms_crm_portal(:key, ''Y'', :name, :email, :phone, :account, :company, :subject, :text, :category); END;'); ORDS.DEFINE_TEMPLATE(p_module_name => v_module, p_pattern => 'crm/t/:tok'); ORDS.DEFINE_HANDLER(p_module_name => v_module, p_pattern => 'crm/t/:tok', p_method => 'GET', p_source_type => ORDS.source_type_plsql, p_source => 'BEGIN wms_crm_tk(:tok, ''N'', NULL, NULL, NULL); END;'); ORDS.DEFINE_HANDLER(p_module_name => v_module, p_pattern => 'crm/t/:tok', p_method => 'POST', p_source_type => ORDS.source_type_plsql, p_source => 'BEGIN wms_crm_tk(:tok, ''Y'', :text, :rate, :comment); END;'); COMMIT; END;
/
